pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        // Ensure caller is not blacklisted initially
        bool initialBlacklisted = c.blacklist(caller);
        vm.assume(!initialBlacklisted);

        // set caller's balance to cover any potential value requirement (optional, but safe)
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        // Call XBornID() to trigger distribution and blacklist logic
        c.XBornID();

        // The reference C should NOT blacklist a non-blacklisted caller after XBornID()
        // because blacklist flag is only set in getTokens() if toGive > 0, but XBornID does not call getTokens.
        assertTrue(c.blacklist(caller) == false);
    }
}

