pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 burnAmount) public {
        // Bound burnAmount to a valid value: owner has totalDistributed tokens initially
        vm.assume(burnAmount > 0);
        vm.assume(burnAmount <= 200000000e18);

        // Record totalSupply before burn
        uint256 totalSupplyBefore = c.totalSupply();

        // As owner, call burn
        vm.prank(c.owner()); // use public getter for owner
        c.burn(burnAmount);

        // After burn, totalSupply must be less than before (decreased by burnAmount)
        uint256 totalSupplyAfter = c.totalSupply();
        assertTrue(totalSupplyAfter < totalSupplyBefore, "totalSupply should decrease after burn");
    }
}

