import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 value) public {
        vm.assume(caller != address(0));
        vm.assume(value > 0 && value <= c.totalSupply());
        // Give the contract some ether to handle potential payable functions
        vm.deal(address(c), 1 ether);
        // Get totalSupply before burn
        uint256 supplyBefore = c.totalSupply();
        // Try to call burn via the onlyOwner path by pranking the owner
        // Since the owner is set in constructor to msg.sender (this contract), we can use c directly
        vm.prank(address(this));
        (bool success, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", value));
        // The rule: if burn succeeded, totalSupply must not have increased
        if (success) {
            assertTrue(c.totalSupply() <= supplyBefore);
        }
    }
}

