pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property() public {
        // Call XBornID() to trigger the initialization
        c.XBornID();
        // The property: totalSupply should equal 500000000e18 (the original constant) after XBornID()
        // In the reference, totalSupply stays initial; in the mutant, it stays initial as well because burn is not called
        // But the bug only manifests when burn is called after XBornID(). To capture the difference,
        // we must call burn first. However, burn requires onlyOwner. We will prank as owner.
        // Use vm.prank to set msg.sender to owner. But owner is set to msg.sender in constructor.
        // In setUp, we deployed as the test contract, so owner is the test contract itself.
        // We can call burn with a non-zero value.
        // First, fund the owner's balance. Since totalDistributed is 200000000e18 and balances[owner] is set to that in XBornID? Actually XBornID() sets balances[owner] = totalDistributed.
        // So after XBornID, owner has 200000000e18. We'll burn some.
        // But to make the test fuzz-friendly, we use a fixed burn amount that is <= owner's balance.
        uint256 burnAmount = 1e18;
        // Ensure owner has enough balance (which they do after XBornID)
        c.XBornID();
        c.burn(burnAmount);
        // After burn in the reference, totalSupply = 500000000e18 - burnAmount
        // In the mutant, totalSupply = 0.
        // So the property: totalSupply should be > 0 after any burn with non-zero amount.
        // More precisely: totalSupply should be exactly 500000000e18 - burnAmount for the reference.
        // But fuzz: we can say totalSupply >= totalDistributed after burn? No.
        // Instead we assert a general rule: totalSupply equals the constant minus the burned amount in reference, but in mutant it's 0.
        // A simple rule: totalSupply must be greater than or equal to the maximum of 0 and something? 
        // The cleanest: After XBornID() and any burn, totalSupply should be at least totalDistributed.
        // But after burn, totalDistributed decreases too. So totalSupply >= totalDistributed always holds.
        // In mutant, totalSupply=0 but totalDistributed might be >0 if burnAmount < totalDistributed. So property fails.
        assertTrue(c.totalSupply() >= c.totalDistributed());
    }
}

