pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 totalRemainingValue, address caller) public {
        // Bound inputs to valid range
        totalRemainingValue = bound(totalRemainingValue, 0, c.totalSupply());
        vm.assume(caller != address(0));

        // Ensure the caller is not blacklisted
        vm.prank(caller);
        // We will not call XBornID() before the test to set totalRemaining to a known state;
        // instead we directly trigger the state where value == totalRemaining.
        // Use vm.prank to call getTokens() via XBornID() which calls distr and updates value.
        // But the rule is: when value == totalRemaining, the reference succeeds and M reverts.
        // We can achieve this by initializing totalRemaining to equal value.
        // Since value is public, we can set it artificially via the contract's internal logic?
        // Actually, we cannot set totalRemaining directly as it's private.
        // Alternative approach: use vm.assume to ensure that after the call, the revert happens in M.
        // Simpler: we know in P, getTokens() works when value == totalRemaining;
        // in M, it reverts. So we test that after XBornID(), the value field is updated in P.
        // Better: directly call getTokens() with a condition that sets up value == totalRemaining.
        // Since totalRemaining is computed from totalSupply and totalDistributed,
        // we can set up initial state by burning tokens to adjust totalDistributed.
        // But that's complex. Instead, we observe that after XBornID(), totalRemaining decreases.
        // The difference is simply: in P, when getTokens() is called and value == totalRemaining,
        // the call succeeds, and value is updated (value = value * 99999 / 100000). In M, it reverts.
        // So the rule: for any caller, when totalRemaining >= value, calling XBornID() must not revert.
        // And after the call, value must be less than or equal to its previous value.

        // Capture the value state before the call
        uint256 valueBefore = c.value();
        uint256 totalRemainingBefore = c.totalRemaining();

        // Only proceed if value <= totalRemaining (otherwise the require would pass trivially)
        vm.assume(valueBefore <= totalRemainingBefore);

        // Also ensure the caller is not blacklisted (already assumed not address(0))
        vm.prank(caller);

        // Try to call XBornID() which triggers getTokens()
        try c.XBornID() {
            // Success: check value did not increase (in reference it should decrease)
            uint256 valueAfter = c.value();
            assertTrue(valueAfter <= valueBefore, "Value should not increase");
        } catch {
            // If it reverts, then we are in the mutant case and the test should fail
            assertTrue(false, "getTokens should not revert when value <= totalRemaining");
        }
    }
}

