pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        // Ensure totalRemaining is at least 1000e18 so value can be set
        vm.assume(amount >= 1000e18 && amount <= 10**30);

        // Set totalRemaining to amount by manipulating totalDistributed via burn
        // We first need to get some tokens to burn. Call XBornID() to give tokens to owner.
        c.XBornID();
        // Now burn some to reduce totalDistributed and adjust totalRemaining
        // totalRemaining = totalSupply - totalDistributed
        // Initially totalSupply = 500000000e18, totalDistributed = 200000000e18, totalRemaining = 300000000e18
        // After XBornID(), balances[owner] = 200000000e18
        // We need totalRemaining = amount, so totalDistributed = totalSupply - amount
        uint256 targetDistributed = c.totalSupply() - amount;
        uint256 burnAmount = c.totalDistributed() - targetDistributed;
        vm.prank(c.owner());
        c.burn(burnAmount);

        // Now totalRemaining should equal amount
        // Ensure value equals totalRemaining by adjusting value through multiple getTokens calls
        // value starts at 1000e18 and decreases each call
        // We loop until value equals totalRemaining
        while (c.value() != c.totalRemaining()) {
            if (c.value() > c.totalRemaining()) {
                // Need to increase totalRemaining (by burning more) or decrease value
                // Since we can't easily increase value, we decrease totalRemaining by burning more
                // or just revert if impossible
                vm.prank(c.owner());
                c.burn(1e18); // small burn to adjust
            } else {
                // value < totalRemaining, call getTokens to decrement value
                c.XBornID();
            }
        }

        // Now value == totalRemaining
        // Call XBornID() which calls getTokens()
        // In reference, require(value <= totalRemaining) passes; in mutant, require(value < totalRemaining) reverts
        uint256 valueBefore = c.value();
        uint256 totalRemainingBefore = c.totalRemaining();

        // Try calling getTokens via XBornID()
        (bool success, ) = address(c).call(abi.encodeWithSignature("XBornID()"));

        // Rule: The call must succeed (no revert) when value equals totalRemaining
        assertTrue(success, "getTokens should not revert when value equals totalRemaining");
    }
}

