pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialValue, uint256 initialTotalRemaining) public {
        // Bound inputs to reasonable ranges to avoid overflow in set-up
        initialValue = bound(initialValue, 1, 1e27);
        initialTotalRemaining = bound(initialTotalRemaining, initialValue, 1e27);

        // Set up state so that value equals totalRemaining
        // Write directly via vm.store to avoid reverts, then call XBornID()
        vm.store(address(c), bytes32(uint256(3)), bytes32(initialTotalRemaining)); // slot 3 = totalRemaining
        vm.store(address(c), bytes32(uint256(4)), bytes32(initialValue));          // slot 4 = value

        uint256 beforeValue = c.value();
        uint256 beforeTotalRemaining = c.totalRemaining();
        vm.assume(beforeValue == beforeTotalRemaining);

        // Drive call to XBornID() (the only public entry that can affect value)
        // Must call from owner to pass the onlyOwner modifier
        vm.prank(address(this));
        c.XBornID();

        uint256 afterValue = c.value();
        // General rule: when value == totalRemaining before XBornID(), value must decrease (strictly less)
        assertTrue(afterValue < beforeValue, "value should decrease after XBornID when value == totalRemaining");
    }
}

