pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // Operate the contract via the public/external surface
        vm.assume(caller != address(0));
        // call any public functions to drive state (here we call XBornID directly)
        // XBornID() is public, so we can call it
        c.XBornID();

        // After XBornID() completes, check the general rule:
        // distributionFinished should be false.
        // In the reference P, XBornID() does not set distributionFinished, so it remains false.
        // In buggy M, the condition `if (false)` never sets distributionFinished, so it also remains false here.
        // Wait, this property holds for both. Let's re-read the bug description.
        // The bug is that inside getTokens(), the condition `if (totalDistributed >= totalSupply)` is replaced with `if (false)`.
        // But the difference state is that after a call to XBornID(), distributionFinished differs.
        // Actually the reference's getTokens() sets distributionFinished when totalDistributed >= totalSupply, but the mutated version never sets it.
        // So a call to XBornID() alone may not trigger getTokens(). However, the test must drive the contract through a sequence that ends with XBornID() and then check distributionFinished.
        // Better: call getTokens() first via a payable call, then call XBornID().
        // Let's adjust: first call getTokens() (payable to trigger the function), then call XBornID().

        // Reset: deploy fresh
        c = new C();
        // Call getTokens() with some value
        vm.deal(address(this), 1 ether);
        (bool success, ) = address(c).call{value: 1 ether}("");
        require(success, "getTokens failed");
        // Now call XBornID()
        c.XBornID();

        // Now assert: distributionFinished must be false.
        // In the reference, after getTokens(), totalDistributed >= totalSupply might become true and set distributionFinished = true, but then XBornID() does nothing.
        // Actually we need a rule that holds for all fuzz parameters after the sequence: call getTokens() then XBornID().
        // The buggy version never sets distributionFinished, so it will always be false.
        // The reference may set it true if totalDistributed >= totalSupply after getTokens().
        // So after the sequence, distributionFinished will be true for reference if condition true, false for buggy.
        assertTrue(c.distributionFinished() == false, "distributionFinished should be false after XBornID()");
    }
}

