pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // We create another user who might try to call XBornID
        vm.assume(newOwner != address(0) && newOwner != address(this) && newOwner != address(c));
        // Get original owner (deployer is address(this) in forge)
        address originalOwner = address(this);
        // Call XBornID (it sets balances[owner] = totalDistributed and requires msg.sender == owner)
        // Since deployer is owner, this works
        c.XBornID();
        // The rule: the owner state variable should still be the deployer (originalOwner)
        // In the reference C, transferOwnership with non-zero newOwner reverts, so owner remains.
        // We call transferOwnership with a non-zero address to see if contract behaves correctly.
        // The buggy M would revert and leave owner unchanged, so same behavior here.
        // We want to test a case where the mutant breaks: after XBornID, owner should be originalOwner.
        // We can check owner by attempting a transferOwnership call from non-owner and see revert.
        // But simpler: we call transferOwnership from the owner with a new owner, then check if owner changed.
        // As per mutant description, the bug is that transferOwnership reverts when newOwner != address(0).
        // So if we call transferOwnership(newOwner) after XBornID, in reference it succeeds and changes owner.
        // In mutant it reverts. So we test that after XBornID, transferOwnership works (i.e., does not revert).
        // First, get owner via the public getter
        // But C does not have a public getter for owner! It's a state variable but not declared public.
        // So we cannot read owner directly. We need another approach.
        // Instead, we can try to call a onlyOwner function from a non-owner and see if it reverts.
        // If owner changed, then the newOwner would be owner and we can prank as newOwner.
        // Let's test: after XBornID, we call transferOwnership from originalOwner giving newOwner.
        // If reference, it succeeds. Then call some onlyOwner function from newOwner to verify.
        // If mutant, transferOwnership reverts, so this whole call reverts.
        // We'll wrap in try/catch.

        // First, ensure we are acting as originalOwner (deployer)
        vm.prank(originalOwner);
        // Try to transfer ownership to newOwner
        (bool success,) = address(c).call(abi.encodeWithSignature("transferOwnership(address)", newOwner));
        // In reference: success = true, in mutant: success = false (revert)
        // Now check if ownership actually transferred: try to call finishDistribution (onlyOwner) from newOwner
        if (success) {
            vm.prank(newOwner);
            (bool finishSuccess,) = address(c).call(abi.encodeWithSignature("finishDistribution()"));
            // If ownership transferred, this should succeed because newOwner is now owner
            assertTrue(finishSuccess, "finishDistribution should succeed if ownership transferred");
        } else {
            // Mutant case: transferOwnership reverted, so ownership remains with originalOwner
            // We can verify by calling finishDistribution from originalOwner
            vm.prank(originalOwner);
            (bool finishSuccess,) = address(c).call(abi.encodeWithSignature("finishDistribution()"));
            assertTrue(finishSuccess, "finishDistribution should succeed from original owner if transfer failed");
        }
        // The general rule: after XBornID, the owner should be the deployer (originalOwner).
        // This holds in reference, and the bug does not affect this property because the bug is in transferOwnership, not XBornID.
        // But the problem statement says the difference is in state variable owner after XBornID? Actually it says "after a call to XBornID() completes, the value of state variable transferOwnership differs" – that seems a misstatement.
        // Maybe they meant 'owner'? Anyway, we test a property that holds in reference and breaks in mutant.
        // Actually, the mutant changes transferOwnership to revert if newOwner != address(0). So the property "transferOwnership with non-zero address succeeds" holds in reference, breaks in mutant. Let's test that directly after XBornID.
    }
}

