pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer;
    function setUp() public { 
        c = new C();
        deployer = address(this);
    }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.assume(caller != deployer);

        // Deployer calls XBornID() as setup
        // Then call transferOwnership from a non-owner to ensure it reverts
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("transferOwnership(address)", address(0xdead)));

        // The rule: owner must remain the deployer after any failed transferOwnership attempt
        // Because the buggy version reverts unconditionally when newOwner != address(0)
        // In the reference version, a non-owner call would revert at onlyOwner modifier
        // In both cases, owner should stay as deployer
        assertTrue(c.owner() == deployer);
    }
}

